// Each channel has an uploads playlist whose ID is the channel ID with UC changed to UU.
const cfg = $('Config').first().json;
const ids = [];
for (const part of String(cfg.channelIds || '').split(/[\s,]+/).filter(Boolean)) {
  const m = part.match(/UC[A-Za-z0-9_-]{22}/);
  if (!m) {
    throw new Error('"' + part + '" is not a channel ID. Channel IDs start with UC and are 24 characters long. '
      + 'On the channel page click "more", then Share channel, then Copy channel ID.');
  }
  if (!ids.includes(m[0])) ids.push(m[0]);
}
if (!ids.length) throw new Error('Add at least one channel ID to channelIds in the Config node.');
return ids.map((channelId) => ({ json: { channelId, playlistId: 'UU' + channelId.slice(2) } }));

// Keep uploads from the last maxAgeHours, newest first. A channel that could not be read is
// listed in the email; if no channel could be read at all, the run stops with the reason.
const cfg = $('Config').first().json;
const maxAgeMs = Number(cfg.maxAgeHours || 48) * 3600 * 1000;
const channels = $('Build uploads playlist list').all().map((i) => i.json);
const pages = $input.all().map((i) => i.json);
const errText = (e) => String(typeof e === 'string' ? e : (e && (e.message || e.description)) || 'request failed');

const videos = [];
let failed = 0;
let firstError = '';
pages.forEach((page, i) => {
  if (page.error || !Array.isArray(page.items)) {
    failed++;
    firstError = firstError || errText(page.error);
    return;
  }
  for (const it of page.items) {
    const s = it.snippet || {};
    const d = it.contentDetails || {};
    const videoId = d.videoId || (s.resourceId && s.resourceId.videoId);
    const published = d.videoPublishedAt || s.publishedAt;
    if (!videoId || !d.videoPublishedAt) continue; // private and deleted entries have no publish date
    if (Date.now() - Date.parse(published) > maxAgeMs) continue;
    videos.push({
      videoId,
      title: s.title || '',
      channel: s.videoOwnerChannelTitle || s.channelTitle || '',
      channelId: channels[i] ? channels[i].channelId : '',
      published,
    });
  }
});
if (failed === pages.length) {
  throw new Error('The YouTube Data API refused every channel (' + firstError.slice(0, 200) + '). '
    + 'Check the YouTube API key credential and that YouTube Data API v3 is enabled for its project.');
}
if (!videos.length) return [];
videos.sort((a, b) => Date.parse(b.published) - Date.parse(a.published));
// One details call takes up to 50 videos. Any beyond that stay new and come in the next run.
const recent = videos.slice(0, 50);
return [{ json: { ids: recent.map((v) => v.videoId).join(','), videos: recent } }];

// Drop live streams, premieres that haven't aired and videos under minDurationSeconds (most Shorts).
// This runs before "Skip videos already sent", so a premiere is picked up once it has aired.
const cfg = $('Config').first().json;
const minSeconds = Number(cfg.minDurationSeconds ?? 180);
const seconds = (iso) => {
  const m = /^P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(String(iso || ''));
  return m ? (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0) : 0;
};
const details = new Map(($input.first().json.items || []).map((d) => [d.id, d]));
const out = [];
for (const v of $('List recent uploads').first().json.videos) {
  const d = details.get(v.videoId);
  if (!d) continue; // removed or made private since it was listed
  if (((d.snippet && d.snippet.liveBroadcastContent) || 'none') !== 'none') continue;
  const length = seconds(d.contentDetails && d.contentDetails.duration);
  if (length < minSeconds) continue;
  out.push({ json: { ...v, url: 'https://www.youtube.com/watch?v=' + v.videoId, durationSeconds: length } });
}
return out;

// One Apify run for every new video. Videos over maxVideosPerRun are listed in the email without a summary.
const max = Math.max(1, Number($('Config').first().json.maxVideosPerRun || 10));
const all = $input.all().map((i) => i.json);
const videos = all.slice(0, max);
return [{ json: { videoUrls: videos.map((v) => v.url), videos, overflow: all.slice(max) } }];

// Pair each video with its transcript row. A video without a usable transcript is kept,
// with the reason, so the email can list it.
const batch = $('Batch videos for transcripts').first().json;
const rows = $input.all().map((i) => i.json);
const runFailed = rows.length > 0 && rows.every((r) => r.error && !r.videoId && !r.url);
const runError = runFailed
  ? String((rows[0].error && rows[0].error.message) || rows[0].error)
  : '';
const byId = new Map();
for (const r of rows) {
  if (r.videoId) byId.set(r.videoId, r);
}
const REASONS = {
  NO_CAPTIONS: 'the video has no captions',
  EMPTY_TRANSCRIPT: 'the captions are empty',
  NOT_FOUND: 'the video is unavailable',
  LOGIN_REQUIRED: 'the video is private, age-restricted or members-only',
  RESTRICTED: 'the video is private, age-restricted or members-only',
  BLOCKED: 'YouTube refused the transcript request',
};
const MAX_CHARS = 12000;

return batch.videos.map((v) => {
  const r = byId.get(v.videoId);
  if (runError || !r || r.error || !r.text) {
    const reason = runError
      ? 'the transcript request failed (' + runError.slice(0, 200) + ')'
      : !r ? 'no transcript came back for this video'
      : REASONS[r.errorType] || String(r.error || 'no transcript text');
    return { json: { ...v, ok: false, reason } };
  }
  const text = String(r.text);
  return { json: {
    ...v,
    ok: true,
    autoCaptions: r.isAutoGenerated === true,
    lengthMinutes: Math.max(1, Math.round(v.durationSeconds / 60)),
    truncated: text.length > MAX_CHARS,
    transcript: text.slice(0, MAX_CHARS),
  } };
});

