// Build one HTML email. tag() assembles the markup so the workflow JSON holds none.
const LT = String.fromCharCode(60);
const GT = String.fromCharCode(62);
const tag = (t, attrs, inner) => LT + t + (attrs ? ' ' + attrs : '') + GT + (inner || '') + LT + '/' + t + GT;
const esc = (s) => String(s == null ? '' : s).split('&').join('&amp;').split(LT).join('&lt;')
  .split(GT).join('&gt;').split('"').join('&quot;');
const link = (url, text) => tag('a', 'href="' + esc(url) + '" style="color:#1d4ed8"', esc(text));
const day = (iso) => new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
const errText = (e) => String(typeof e === 'string' ? e : (e && (e.message || e.description)) || 'request failed');

const items = $input.all().map((i) => i.json);
const done = items.filter((x) => x.summary && x.summary.tldr);
const missing = items.filter((x) => !(x.summary && x.summary.tldr));
const overflow = $('Batch videos for transcripts').first().json.overflow || [];
const pages = $('Get latest uploads').all().map((i) => i.json);
const down = $('Build uploads playlist list').all()
  .map((c, k) => ({ channelId: c.json.channelId, page: pages[k] || {} }))
  .filter((c) => c.page.error || !Array.isArray(c.page.items));

const RANK = { 'must watch': 0, 'worth a skim': 1, skip: 2 };
const COLOR = { 'must watch': '#15803d', 'worth a skim': '#b45309', skip: '#6b7280' };
done.sort((a, b) => (RANK[a.summary.verdict] ?? 1) - (RANK[b.summary.verdict] ?? 1)
  || Date.parse(b.published) - Date.parse(a.published));

let html = '';
for (const v of done) {
  const s = v.summary;
  const verdict = RANK[s.verdict] === undefined ? 'worth a skim' : s.verdict;
  const meta = [esc(v.channel), day(v.published), v.lengthMinutes ? v.lengthMinutes + ' min' : '']
    .filter(Boolean).join(' · ');
  const badge = tag('span', 'style="color:' + COLOR[verdict] + ';font-weight:600"', esc(verdict));
  const points = (Array.isArray(s.keyPoints) ? s.keyPoints : []).map((p) => tag('li', '', esc(p))).join('');
  html += tag('h3', 'style="margin:22px 0 2px"', link(v.url, v.title))
    + tag('div', 'style="color:#555;font-size:13px"', meta + ' · ' + badge)
    + tag('p', '', esc(s.tldr))
    + (points ? tag('ul', '', points) : '')
    + (s.whoShouldWatch ? tag('p', 'style="color:#555;font-size:13px"', 'Who it is for: ' + esc(s.whoShouldWatch)) : '');
}

const others = missing.map((v) => tag('li', '', link(v.url, v.title) + ' (' + esc(v.channel) + '): '
  + esc(v.reason || ('no summary, ' + (v.summaryError || 'the model call failed')))))
  .concat(overflow.map((v) => tag('li', '', link(v.url, v.title) + ' (' + esc(v.channel)
  + '): over the maxVideosPerRun limit, not summarized')));
if (others.length) html += tag('h3', 'style="margin:28px 0 4px"', 'New, without a summary') + tag('ul', '', others.join(''));

if (down.length) {
  const list = down.map((c) => tag('li', '', link('https://www.youtube.com/channel/' + c.channelId, c.channelId)
    + ': ' + esc(errText(c.page.error).slice(0, 160)) + '. If this keeps happening, check the channel ID.'));
  html += tag('h3', 'style="margin:28px 0 4px"', 'Channels that could not be read today') + tag('ul', '', list.join(''));
}

const total = done.length + missing.length + overflow.length;
const must = done.filter((v) => v.summary.verdict === 'must watch').length;
const subject = 'YouTube digest: ' + total + ' new video' + (total === 1 ? '' : 's')
  + (must ? ', ' + must + ' must watch' : '');
const body = tag('div', 'style="font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;max-width:640px;color:#111;line-height:1.5"',
  tag('h2', 'style="margin:0 0 4px"', esc(subject)) + html
  + tag('p', 'style="color:#888;font-size:12px;margin-top:28px"', 'Sent by your n8n workflow. Transcripts by Apify, summaries by OpenAI.'));
return [{ json: { subject, html: body, videos: total } }];
